function reviewVisibleDraftKey(context,target,methodId='new'){return KEY+':visible-tutorial-draft:'+JSON.stringify([context.ownerId,target.nodeId,target.version,methodId])}
function reviewContributeVisible(target,context,existing=null,history=false){
 if(!reviewContextCurrent(context))return;const key=reviewVisibleDraftKey(context,target,existing?.id||'new');let draft={schema:1,ownerId:context.ownerId,target:clone(target),requestId:uid(),baseVersion:existing?.version||null,fields:{title:existing?.title||'',method:existing?.method||'',startAction:existing?.startAction||target.five,resources:clone(existing?.resources||[])}};
 try{const raw=localStorage.getItem(key);if(raw){const d=JSON.parse(raw);if(d.schema!==1||d.ownerId!==context.ownerId||JSON.stringify(d.target)!==JSON.stringify(target)||typeof d.requestId!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(d.requestId)||(d.baseVersion!==null&&typeof d.baseVersion!=='string')||!Array.isArray(d.fields?.resources)||d.fields.resources.length>12||d.fields.resources.some(r=>!r||typeof r!=='object'||Array.isArray(r)||Object.keys(r).some(k=>!['label','url','optional','affiliate'].includes(k))||typeof r.label!=='string'||typeof r.url!=='string'||typeof r.optional!=='boolean'||typeof r.affiliate!=='boolean')||['title','method','startAction'].some(k=>typeof d.fields[k]!=='string'))throw Error('已有草稿无法核对，原内容未覆盖。');draft=d}}catch(e){modal(`<h2>草稿未能读取</h2><p>${esc(e.message)}</p><button id="visible-draft-raw">导出原草稿</button>`,'','贡献草稿状态');document.getElementById('visible-draft-raw').addEventListener('click',()=>{const raw=localStorage.getItem(key);download('公开目标-原草稿.json',{format:'dianliang-visible-tutorial-raw/v1',raw})});return}
 modal(`<h2>${existing?'修订教程':'贡献教程'}</h2><p class="small muted">${esc(target.title)} · 目标 v${target.sourceVersion}</p><details class="saved-notes"><summary>核对完整目标</summary><p class="pre">${esc(target.goal)}</p></details><form id="visible-contribution-form" class="stack"><label class="field">教程名称<input name="title" aria-label="公开目标教程名称" maxlength="80" required value="${esc(draft.fields.title)}"></label><label class="field">具体步骤<textarea name="method" aria-label="公开目标教程步骤" maxlength="8000" required>${esc(draft.fields.method)}</textarea></label><label class="field">下一段五分钟<input name="startAction" aria-label="公开目标教程五分钟" maxlength="240" value="${esc(draft.fields.startAction)}"></label><section><h3>资料与产品</h3><p class="small muted">逐项记录材料及外链用途。分成标记不产生交易。</p><div id="visible-contribution-resources"></div><button type="button" id="visible-resource-add" class="ghost">添加资料</button></section><label class="field">保存范围<select name="visibility" aria-label="公开目标教程保存范围"><option value="private">私人保存到本人账号</option><option value="public">公开给其他账号</option></select></label><label id="visible-contribution-consent" class="check-row" hidden><input type="checkbox" name="consent">我确认公开以上教程及材料；私人笔记和实践证据不公开</label><p id="visible-contribution-error" class="error" role="alert"></p><p id="visible-contribution-status" class="small muted" role="status"></p><button class="primary" id="visible-contribution-submit">确认保存教程</button></form><div class="row actions"><button id="visible-contribution-export" class="ghost">导出当前草稿</button></div>`,'','贡献公开目标教程');
 const form=document.getElementById('visible-contribution-form'),status=document.getElementById('visible-contribution-status'),error=document.getElementById('visible-contribution-error'),host=document.getElementById('visible-contribution-resources');let busy=false;
 function fields(){for(const k of ['title','method','startAction'])draft.fields[k]=form.elements.namedItem(k).value;return clone(draft.fields)}
 function keep(){if(!form.isConnected||!reviewContextCurrent(context))return false;fields();try{const raw=JSON.stringify(draft);localStorage.setItem(key,raw);if(localStorage.getItem(key)!==raw)throw Error('Not saved');status.textContent='草稿已暂存到本机，公开选项不随草稿恢复。';return true}catch{status.textContent='草稿暂存未完成，请导出当前内容后再刷新。';return false}}
 function resources(){host.innerHTML=draft.fields.resources.map((r,i)=>`<fieldset class="stack" style="border:1px solid var(--border);padding:12px;margin-top:12px"><legend>资料 ${i+1}</legend><label class="field">名称<input data-field="label" aria-label="贡献资料 ${i+1} 名称" maxlength="80" value="${esc(r.label)}"></label><label class="field">地址<input data-field="url" aria-label="贡献资料 ${i+1} 地址" value="${esc(r.url)}"></label><label class="check-row"><input type="checkbox" data-field="optional" ${r.optional?'checked':''}>可选材料</label><label class="check-row"><input type="checkbox" data-field="affiliate" ${r.affiliate?'checked':''}>分成产品外链</label><button type="button" data-remove="${i}" class="ghost">移除此项</button></fieldset>`).join('');host.querySelectorAll('fieldset').forEach((row,i)=>{row.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('input',()=>{if(!input.isConnected||!reviewContextCurrent(context))return;draft.fields.resources[i][input.dataset.field]=input.type==='checkbox'?input.checked:input.value;keep()}));row.querySelector('[data-remove]').addEventListener('click',()=>{if(!row.isConnected||!reviewContextCurrent(context))return;draft.fields.resources.splice(i,1);resources();keep()})})}
 resources();for(const k of ['title','method','startAction'])form.elements.namedItem(k).addEventListener('input',keep);
 document.getElementById('visible-resource-add').addEventListener('click',()=>{if(!form.isConnected||!reviewContextCurrent(context))return;if(draft.fields.resources.length>=12){error.textContent='最多十二项资料，当前材料保留。';return}draft.fields.resources.push({label:'',url:'',optional:true,affiliate:false});resources();keep()});
 const scope=form.elements.namedItem('visibility'),consent=form.elements.namedItem('consent');if(history){scope.querySelector('[value=public]').disabled=true;status.textContent='历史目标保留，本入口只修订私人版本。'}scope.addEventListener('change',()=>{document.getElementById('visible-contribution-consent').hidden=scope.value!=='public';consent.required=scope.value==='public';consent.checked=false});
 document.getElementById('visible-contribution-export').addEventListener('click',()=>{fields();download('公开目标-教程草稿.json',{format:'dianliang-visible-tutorial-draft/v1',...clone(draft)})});
 form.addEventListener('submit',async ev=>{ev.preventDefault();if(busy||!form.isConnected||!reviewContextCurrent(context)||!form.reportValidity())return;busy=true;const button=document.getElementById('visible-contribution-submit');button.disabled=true;error.textContent='';
  try{const value=fields();validateResourceLinks(value.resources);value.resources=value.resources.map(r=>({label:r.label.trim(),url:new URL(r.url).href,affiliate:r.affiliate,optional:r.optional}));for(const k of ['title','method','startAction'])value[k]=value[k].trim();const visibility=scope.value;if(visibility==='public'&&!consent.checked)throw Error('公开需单独确认；可以先私人保存。');if(!keep())throw Error('请先导出或成功暂存草稿后再提交。');const fingerprint=JSON.stringify(fields());
   const current=history?await reviewKnowledgeRequest('/api/review-visible-targets/my-tutorials',{context}):await reviewKnowledgeRequest('/api/review-visible-targets/one?nodeId='+encodeURIComponent(target.nodeId),{context});if(history){const original=current.tutorials?.find(t=>t.id===existing.id);if(current.ownerId!==context.ownerId||!original||JSON.stringify(original.targetSnapshot)!==JSON.stringify(target))throw Error('原目标快照已变化，草稿保留。');current.target=original.targetSnapshot;}if(!form.isConnected||!reviewContextCurrent(context))return;if(JSON.stringify(current.target)!==JSON.stringify(target))throw Error('目标已变化，草稿保留，请重新核对目标版本。');
   const owned=await reviewKnowledgeRequest(history?'/api/review-visible-targets/my-tutorials':'/api/tutorials?nodeId='+encodeURIComponent(target.nodeId)+'&treeId='+encodeURIComponent(target.treeId),{context});if(!form.isConnected||!reviewContextCurrent(context))return;
   const saved=owned.tutorials?.find(t=>t.authorId===context.ownerId&&(existing?t.id===existing.id:t.creationRequest?.id===draft.requestId)&&t.targetSnapshot?.version===target.version&&t.visibility===visibility&&['title','method','startAction'].every(k=>t[k]===value[k])&&JSON.stringify(t.resources)===JSON.stringify(value.resources));
   const result=saved?{tutorial:saved,repeated:true}:await reviewKnowledgeRequest(existing?'/api/tutorials/'+encodeURIComponent(existing.id):'/api/tutorials',{context,method:existing?'PATCH':'POST',headers:existing?{'If-Match':draft.baseVersion}:{},body:{treeId:target.treeId,nodeId:target.nodeId,targetVersion:target.version,requestId:draft.requestId,...value,visibility}});if(!form.isConnected||!reviewContextCurrent(context))return;const t=result.tutorial;
   if(t?.authorId!==context.ownerId||t.targetSnapshot?.version!==target.version||t.visibility!==visibility||['title','method','startAction'].some(k=>t[k]!==value[k])||JSON.stringify(t.resources)!==JSON.stringify(value.resources))throw Error('保存回执与提交不一致，草稿保留，请重新核对。');
   if(JSON.stringify(fields())!==fingerprint){draft.savedReceipt={id:t.id,version:t.version};keep();status.textContent='服务已保存提交时的内容，之后的新编辑仍在草稿中。请核对已保存版本再修订。';return}
   localStorage.removeItem(key);closeModal();toast(visibility==='public'?'服务已确认公开教程，目标版本和材料保留。':'教程已私人保存到本人账号，未自动公开。');
  }catch(e){if(form.isConnected&&reviewContextCurrent(context))error.textContent=reviewIsNetworkError(e)?'连接未完成，草稿保留。可重试核对；同一次提交不会重复创建教程。':e.message}finally{busy=false;button.disabled=false}
 });
}
